def _is_sorted(xs):
    for k in range(len(xs) - 1):
        if xs[k] > xs[k + 1]:
            return False
    return True


def pre(a, b):
    if len(a) > 4 or len(b) > 4:
        return False
    for x in a:
        if x < -9 or x > 9:
            return False
    for x in b:
        if x < -9 or x > 9:
            return False
    return _is_sorted(a) and _is_sorted(b)


def post(a, b, result):
    # The required output is the unique non-decreasing arrangement of the
    # multiset union of a and b, which is exactly sorted(a + b).
    combined = a.copy()
    combined.extend(b)
    expected = sorted(combined)
    if len(result) != len(expected):
        return False
    for k in range(len(expected)):
        if result[k] != expected[k]:
            return False
    return True
